const PR21=[{label:"Ví dụ: Leo cầu thang",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;                         // đứng ở chân cầu thang: 1 cách\n    for (int i = 1; i <= n; i++) {\n        dp[i] = dp[i - 1];             // bước cuối là 1 bậc\n        if (i >= 2) dp[i] += dp[i - 2];   // bước cuối là 2 bậc\n    }\n    cout << dp[n] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["i"]}]},{label:"Ví dụ: Ít đồng xu nhất",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> xu = {1, 3, 4};\n    int S = 6;\n    const int INF = 1e9;\n    vector<int> dp(S + 1, INF);\n    dp[0] = 0;\n    for (int s = 1; s <= S; s++)\n        for (int c : xu)\n            if (c <= s && dp[s - c] + 1 < dp[s]) dp[s] = dp[s - c] + 1;\n    cout << dp[S] << \"\\n\";             // 3 + 3\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["s"]}]},{label:"Ví dụ: Đếm cách không thứ tự",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> xu = {1, 2, 5};\n    int S = 5;\n    vector<long long> dp(S + 1, 0);\n    dp[0] = 1;\n    for (int c : xu)                   // vòng ngoài là đồng xu\n        for (int s = c; s <= S; s++)\n            dp[s] += dp[s - c];\n    cout << dp[S] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["s"]},{type:"vars",names:["c"]}]}];
const sim21=makeSim2(document.getElementById("sim-l21"),{id:"s21",presets:PR21,tools:true});
makeEx2(document.getElementById("ex-l21"),sim21,[{t:"Cầu thang",d:"File CAUTHANG.INP chứa n (1 ≤ n ≤ 10⁶). Mỗi bước lên được 1, 2 hoặc 3 bậc. Ghi vào CAUTHANG.OUT số cách lên đúng bậc n, chia lấy dư cho 10⁹ + 7.",tests:[{in:"4",out:"7"},{in:"1",out:"1"},{in:"2",out:"2"},{in:"3",out:"4"},{in:"30",out:"53798080"},{in:"1000",out:"509672692"},{in:"20000",out:"886919695"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long tinh(int i) {               // đệ quy không nhớ: gọi lại cùng i rất nhiều lần\n    if (i == 0) return 1;\n    long long s = 0;\n    for (int k = 1; k <= 3; k++)\n        if (i >= k) s += tinh(i - k);\n    return s % 1000000007;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CAUTHANG.INP\", \"r\")) {\n        freopen(\"CAUTHANG.INP\", \"r\", stdin);\n        freopen(\"CAUTHANG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    cout << tinh(n) << \"\\n\";\n    return 0;\n}",file:"CAUTHANG",perf:{gen:n=>String(n),ns:[200,800,3200],need:"n",limit:n=>80*n+500,why:"Mảng dp tính mỗi bậc một lần: O(n)."}},{t:"Ít đồng xu nhất",d:"File DOITIEN.INP: dòng 1 là n, S (1 ≤ n ≤ 100, 1 ≤ S ≤ 10⁵); dòng 2 là n mệnh giá khác nhau (1 ≤ cᵢ ≤ 10⁵), mỗi loại có không giới hạn số đồng. Ghi vào DOITIEN.OUT số đồng ít nhất có tổng đúng bằng S, hoặc −1 nếu không thể.",tests:[{in:"3 6\n1 3 4",out:"2"},{in:"1 3\n2",out:"-1"},{in:"2 1\n5 7",out:"-1"},{in:"1 100000\n1",out:"100000"},{in:"3 6\n4 3 1",out:"2"},{in:"6 997\n12 28 46 58 42 20",out:"-1"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DOITIEN.INP\", \"r\")) {\n        freopen(\"DOITIEN.INP\", \"r\", stdin);\n        freopen(\"DOITIEN.OUT\", \"w\", stdout);\n    }\n    int n, S;\n    cin >> n >> S;\n    vector<int> c(n);\n    for (auto& x : c) cin >> x;\n    sort(c.rbegin(), c.rend());        // tham lam: lấy đồng lớn nhất trước\n    int dem = 0;\n    for (int x : c) { dem += S / x; S %= x; }\n    cout << (S == 0 ? dem : -1) << \"\\n\";\n    return 0;\n}",file:"DOITIEN",perf:{gen:n=>"5 "+(n*20)+"\n1 7 13 29 31",ns:[100,400,1600],need:"n",limit:n=>400*n+2000,why:"O(n · S) với n mệnh giá."}},{t:"Số cách trả tiền",d:"File TRATIEN.INP: dòng 1 là n, S (1 ≤ n ≤ 100, 1 ≤ S ≤ 10⁵); dòng 2 là n mệnh giá khác nhau (1 ≤ cᵢ ≤ 10⁵). Đếm số cách trả đúng S đồng, không phân biệt thứ tự các đồng (2 + 1 và 1 + 2 là một cách). Ghi vào TRATIEN.OUT kết quả chia lấy dư cho 10⁹ + 7.",tests:[{in:"3 5\n1 2 5",out:"4"},{in:"1 3\n2",out:"0"},{in:"1 1\n1",out:"1"},{in:"4 10\n2 3 5 6",out:"5"},{in:"3 1000\n1 2 3",out:"83834"},{in:"8 2000\n31 14 49 33 12 46 34 16",out:"179161532"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TRATIEN.INP\", \"r\")) {\n        freopen(\"TRATIEN.INP\", \"r\", stdin);\n        freopen(\"TRATIEN.OUT\", \"w\", stdout);\n    }\n    int n, S;\n    cin >> n >> S;\n    vector<int> c(n);\n    for (auto& x : c) cin >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(S + 1, 0);\n    dp[0] = 1;\n    for (int s = 1; s <= S; s++)       // vòng tổng ở ngoài: đếm cả thứ tự\n        for (int x : c)\n            if (x <= s) dp[s] = (dp[s] + dp[s - x]) % MOD;\n    cout << dp[S] << \"\\n\";\n    return 0;\n}",file:"TRATIEN"}]);

